'use client';

import { useLayoutEffect, useRef } from 'react';

import { WordRoll } from '@/components/core/word-roll';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import {
  pressedSolidOf,
  spokenUnless,
} from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';
import { Segments, type Segment } from '@/registry/ndeko/ui/segments';

import {
  AGENT_ORDER,
  AGENTS,
  CHANGE_ORDER,
  CHANGES,
  COMMENT,
  DOC_TITLE,
  PARAGRAPHS,
  type AgentId,
} from './data';
import {
  AgentPointer,
  AgentTile,
  ParagraphRow,
  POINTER_REACH,
} from './doc-parts';
import {
  INITIAL,
  LOOP_AFTER_MS,
  pendingIdsOf,
  reducer,
  RESTING,
  SCRIPT,
  type ChangeStatus,
  type CommentStatus,
  type DocState,
  type DocView,
} from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const VIEW_SEGMENTS: Segment<DocView>[] = [
  { value: 'doc', label: 'Doc' },
  { value: 'table', label: 'Table' },
];

const CHANGE_WORD: Record<ChangeStatus, string> = {
  hidden: 'Not started',
  typing: 'Being written',
  pending: 'Suggested',
  accepted: 'Accepted',
  rejected: 'Rejected',
};

const CHANGE_VARIANT = {
  hidden: 'secondary',
  typing: 'secondary',
  pending: 'warning',
  accepted: 'success',
  rejected: 'secondary',
} as const;

const COMMENT_WORD: Record<CommentStatus, string> = {
  hidden: 'Not started',
  typing: 'Being written',
  posted: 'Open',
  resolved: 'Resolved',
};

const COMMENT_VARIANT = {
  hidden: 'secondary',
  typing: 'secondary',
  posted: 'warning',
  resolved: 'success',
} as const;

function pendingPhraseOf(count: number) {
  if (count === 0) {
    return 'No suggestion to decide';
  }
  if (count === 1) {
    return '1 suggestion to decide';
  }
  return `${count} suggestions to decide`;
}

function pointersHiddenOf(view: DocView) {
  if (view === 'table') {
    return 'hidden';
  }
  return undefined;
}

type TableRow = {
  key: string;
  summary: string;
  author: AgentId;
  kind: string;
  word: string;
  variant: 'secondary' | 'warning' | 'success';
};

function rowsOf(state: DocState): TableRow[] {
  const rows: TableRow[] = [];
  for (const id of CHANGE_ORDER) {
    const status = state.changes[id];
    if (status !== 'hidden') {
      rows.push({
        key: id,
        summary: CHANGES[id].summary,
        author: CHANGES[id].author,
        kind: 'Edit',
        word: CHANGE_WORD[status],
        variant: CHANGE_VARIANT[status],
      });
    }
  }
  if (state.comment !== 'hidden') {
    rows.push({
      key: 'comment',
      summary: COMMENT.summary,
      author: COMMENT.author,
      kind: 'Comment',
      word: COMMENT_WORD[state.comment],
      variant: COMMENT_VARIANT[state.comment],
    });
  }
  return rows;
}

function ChangeTable({ rows }: { rows: TableRow[] }) {
  if (rows.length === 0) {
    return (
      <p className='text-muted-foreground py-10 text-center text-[13px]'>
        No change yet. Suggestions and comments are listed here as the agents
        make them.
      </p>
    );
  }
  return (
    <table className='w-full text-start text-[13px]'>
      <thead>
        <tr className='text-muted-foreground text-xs'>
          <th className='pb-2 text-start font-normal'>Change</th>
          <th className='pb-2 text-start font-normal'>Author</th>
          <th className='pb-2 text-end font-normal'>State</th>
        </tr>
      </thead>
      <tbody>
        {rows.map((row) => (
          <tr key={row.key} className='hairline-t border-border'>
            <td className='py-2.5 pe-3'>
              <span className='flex flex-col leading-snug'>
                {row.summary}
                <span className='text-muted-foreground text-xs'>
                  {row.kind}
                </span>
              </span>
            </td>
            <td className='py-2.5 pe-3'>
              <span className='flex items-center gap-2'>
                <AgentTile agent={AGENTS[row.author]} />
                <span className='hidden @md:inline'>
                  {AGENTS[row.author].name}
                </span>
                <span className='sr-only @md:hidden'>
                  {AGENTS[row.author].name}
                </span>
              </span>
            </td>
            <td className='py-2.5 text-end'>
              <Badge variant={row.variant}>
                <Swap swapKey={row.word}>{row.word}</Swap>
              </Badge>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

export default function AgentReview05() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const pageRef = useRef<HTMLDivElement>(null);
  const pendingCount = pendingIdsOf(state).length;
  const pendingPhrase = pendingPhraseOf(pendingCount);
  const hasPending = pendingCount > 0;
  const message = spokenUnless(isAutoplaying, pendingPhrase);
  const canReplay = isFinished && !isAutoplaying;
  const isDoc = state.view === 'doc';
  const writerTarget = state.pointers.writer.target;
  const reviewerTarget = state.pointers.reviewer.target;

  useLayoutEffect(() => {
    const page = pageRef.current;
    if (!page) {
      return;
    }
    const targets = { writer: writerTarget, reviewer: reviewerTarget };
    const place = () => {
      const bounds = page.getBoundingClientRect();
      for (const agent of AGENT_ORDER) {
        const pointer = page.querySelector<HTMLElement>(
          `[data-pointer='${agent}']`
        );
        const paragraph = page.querySelector(
          `[data-paragraph='${targets[agent]}']`
        );
        if (pointer && paragraph) {
          const box = paragraph.getBoundingClientRect();
          const x = box.left - bounds.left + box.width * POINTER_REACH[agent];
          const y = box.top - bounds.top + 18;
          pointer.style.translate = `${x}px ${y}px`;
        }
      }
    };
    place();
    const observer = new ResizeObserver(place);
    observer.observe(page);
    return () => observer.disconnect();
  }, [writerTarget, reviewerTarget, isDoc]);

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full p-3 @3xl:p-8'
      >
        <div className='mx-auto flex max-w-4xl flex-col gap-3'>
          <div className='flex flex-wrap items-center gap-x-3 gap-y-2'>
            <Segments
              label='View'
              value={state.view}
              segments={VIEW_SEGMENTS}
              onValueChange={(view) => act({ type: 'view', view })}
            />
            <span className='text-muted-foreground min-w-40 flex-1 text-xs'>
              <WordRoll text={pendingPhrase} value={pendingCount} />
            </span>
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Replay the edits'
            />
            <Button
              type='button'
              size='sm'
              disabled={!hasPending}
              onClick={() => act({ type: 'acceptAll' })}
              className={pressedSolidOf(pressed === 'accept-all')}
            >
              Accept all
            </Button>
          </div>

          <article
            ref={pageRef}
            aria-label={DOC_TITLE}
            className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] relative flex min-h-[26rem] flex-col gap-6 rounded-xl p-5 shadow-[0_1px_2px_rgb(0_0_0/0.04)] @3xl:p-10'
          >
            <header className='flex flex-col gap-2'>
              <h1 className='text-2xl font-semibold text-balance'>
                {DOC_TITLE}
              </h1>
              <ul
                aria-label='Agents in this document'
                className='flex flex-wrap items-center gap-x-4 gap-y-1'
              >
                {AGENT_ORDER.map((agent) => (
                  <li
                    key={agent}
                    className='text-muted-foreground flex items-center gap-2 text-xs'
                  >
                    <AgentTile agent={AGENTS[agent]} />
                    {AGENTS[agent].name}
                    <Swap swapKey={state.pointers[agent].action}>
                      {state.pointers[agent].action}
                    </Swap>
                  </li>
                ))}
                <li className='text-muted-foreground text-xs'>
                  Illustrative spend
                </li>
              </ul>
            </header>

            {isDoc &&
              PARAGRAPHS.map((paragraph) => (
                <ParagraphRow
                  key={paragraph.id}
                  paragraph={paragraph}
                  statuses={state.changes}
                  pressed={pressed}
                  isActive={isInView}
                  comment={state.comment}
                  onDecide={(id, decision) =>
                    act({ type: 'decided', id, decision })
                  }
                  onResolveComment={() =>
                    act({ type: 'comment', status: 'resolved' })
                  }
                />
              ))}
            {!isDoc && <ChangeTable rows={rowsOf(state)} />}

            <div className={cn(pointersHiddenOf(state.view))}>
              {AGENT_ORDER.map((agent) => (
                <AgentPointer
                  key={agent}
                  agent={AGENTS[agent]}
                  pointer={state.pointers[agent]}
                />
              ))}
            </div>
          </article>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useEffect, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { formatCost, seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { CheckIcon, MousePointerIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';

import {
  AGENTS,
  CHANGES,
  COMMENT,
  type AgentId,
  type ChangeId,
  type DocAgent,
  type Paragraph,
  type Segment,
} from './data';
import {
  TYPE_TICK_MS,
  type ChangeStatus,
  type CommentStatus,
  type Decision,
  type Pointer,
} from './session';

function gemStyleOf(agent: DocAgent) {
  return { '--gem': seriesColorOf(agent.series) } as React.CSSProperties;
}

/** The inserted words carry the author's colour as a line and a tint; the text itself stays the text colour. */
function insertStyleOf(agent: DocAgent): React.CSSProperties {
  const color = seriesColorOf(agent.series);
  return {
    textDecorationColor: color,
    backgroundColor: `color-mix(in oklab, ${color} 14%, transparent)`,
  };
}

export function AgentTile({ agent }: { agent: DocAgent }) {
  return (
    <span
      aria-hidden='true'
      style={gemStyleOf(agent)}
      className='gem-plate inline-flex size-6 shrink-0 items-center justify-center rounded-md text-[10px] font-semibold select-none'
    >
      {agent.initial}
    </span>
  );
}

function useTypedCount(total: number, isTyping: boolean) {
  const [count, setCount] = useState(0);

  useEffect(() => {
    if (!isTyping) {
      return;
    }
    const timer = setInterval(() => {
      setCount((current) => Math.min(total, current + 1));
    }, TYPE_TICK_MS);
    return () => clearInterval(timer);
  }, [isTyping, total]);

  return count;
}

const INSERT_CLASS =
  'rounded-[3px] underline decoration-2 underline-offset-[3px]';

/** Only these words re-render while a suggestion types itself. */
function TypedInsert({
  text,
  agent,
  isActive,
}: {
  text: string;
  agent: DocAgent;
  isActive: boolean;
}) {
  const count = useTypedCount(text.length, isActive);
  const typed = text.slice(0, count);

  return (
    <ins style={insertStyleOf(agent)} className={INSERT_CLASS}>
      {typed}
      <span
        aria-hidden='true'
        className='bg-foreground/60 ms-px inline-block h-[1em] w-[2px] animate-pulse rounded-full align-[-0.15em]'
      />
    </ins>
  );
}

function pressedOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-90 bg-success/25';
  }
  return undefined;
}

type ChangeHandlers = {
  statuses: Record<ChangeId, ChangeStatus>;
  pressed: string | null;
  isActive: boolean;
  onDecide: (id: ChangeId, decision: Decision) => void;
};

const DECISION_BUTTON =
  'focus-visible:ring-ring/40 inline-flex size-5 cursor-pointer items-center justify-center rounded-md outline-none transition-[background-color,scale] duration-150 focus-visible:ring-[3px] active:scale-[0.97]';

function TrackedChangeView({
  id,
  statuses,
  pressed,
  isActive,
  onDecide,
}: ChangeHandlers & { id: ChangeId }) {
  const change = CHANGES[id];
  const agent = AGENTS[change.author];
  const status = statuses[id];
  const hasRemoval = change.removed !== '';
  const isOriginal = status === 'hidden' || status === 'rejected';

  if (isOriginal) {
    return <span>{change.removed}</span>;
  }
  if (status === 'accepted') {
    return (
      <span className='bg-success/0 starting:bg-success/25 rounded-[3px] transition-colors duration-1000 ease-out'>
        {change.inserted}
      </span>
    );
  }
  return (
    <span>
      {hasRemoval && (
        <del className='text-muted-foreground decoration-foreground/40'>
          {change.removed}
        </del>
      )}
      {hasRemoval && ' '}
      {status === 'typing' && (
        <TypedInsert text={change.inserted} agent={agent} isActive={isActive} />
      )}
      {status === 'pending' && (
        <>
          <ins style={insertStyleOf(agent)} className={INSERT_CLASS}>
            {change.inserted}
          </ins>
          <span className='bg-card hairline-ring ring-foreground/15 dark:bg-foreground/[0.08] ms-1.5 inline-flex items-center gap-0.5 rounded-lg p-0.5 align-middle shadow-[0_1px_2px_rgb(0_0_0/0.05)] transition-opacity duration-300 starting:opacity-0'>
            <button
              type='button'
              aria-label={`Accept the suggestion by ${agent.name}: ${change.summary}`}
              onClick={() => onDecide(id, 'accepted')}
              className={cn(
                DECISION_BUTTON,
                'text-success-foreground hover:bg-success/15',
                pressedOf(pressed === `accept-${id}`)
              )}
            >
              <CheckIcon className='size-3.5' />
            </button>
            <button
              type='button'
              aria-label={`Reject the suggestion by ${agent.name}: ${change.summary}`}
              onClick={() => onDecide(id, 'rejected')}
              className={cn(
                DECISION_BUTTON,
                'text-destructive-ink hover:bg-destructive/10'
              )}
            >
              <XIcon className='size-3.5' />
            </button>
          </span>
        </>
      )}
    </span>
  );
}

function SegmentView({
  segment,
  ...handlers
}: ChangeHandlers & { segment: Segment }) {
  if ('text' in segment) {
    return <span>{segment.text}</span>;
  }
  return <TrackedChangeView id={segment.change} {...handlers} />;
}

function TypingDots({ name }: { name: string }) {
  return (
    <span className='flex h-5 items-center gap-1' role='status'>
      <span className='sr-only'>{name} is writing a comment</span>
      <span className='bg-muted-foreground size-1.5 animate-pulse rounded-full' />
      <span className='bg-muted-foreground size-1.5 animate-pulse rounded-full [animation-delay:160ms]' />
      <span className='bg-muted-foreground size-1.5 animate-pulse rounded-full [animation-delay:320ms]' />
    </span>
  );
}

type MarginCommentProps = {
  status: CommentStatus;
  onResolve: () => void;
};

function MarginComment({ status, onResolve }: MarginCommentProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const rowPresence = rowPresenceOf(shouldReduceMotion);
  const agent = AGENTS[COMMENT.author];
  const isShown = status === 'typing' || status === 'posted';

  return (
    <AnimatePresence initial={false}>
      {isShown && (
        <motion.aside
          key='comment'
          aria-label={`Comment by ${agent.name}`}
          className='overflow-hidden'
          {...rowPresence}
        >
          <div className='bg-foreground/[0.04] mt-2 flex flex-col gap-1.5 rounded-lg p-2.5 @3xl:mt-0'>
            <div className='flex items-center gap-2'>
              <AgentTile agent={agent} />
              <span className='text-xs font-medium'>{agent.name}</span>
            </div>
            {status === 'typing' && <TypingDots name={agent.name} />}
            {status === 'posted' && (
              <p className='text-[13px] leading-snug transition-opacity duration-300 starting:opacity-0'>
                {COMMENT.text}
              </p>
            )}
            {status === 'posted' && (
              <Button
                type='button'
                variant='ghost'
                size='sm'
                onClick={onResolve}
                className='text-muted-foreground -ms-1.5 w-fit'
              >
                Resolve
              </Button>
            )}
          </div>
        </motion.aside>
      )}
    </AnimatePresence>
  );
}

type ParagraphRowProps = ChangeHandlers & {
  paragraph: Paragraph;
  comment: CommentStatus;
  onResolveComment: () => void;
};

export function ParagraphRow({
  paragraph,
  comment,
  onResolveComment,
  ...handlers
}: ParagraphRowProps) {
  const hasComment = COMMENT.paragraph === paragraph.id;

  return (
    <div className='grid gap-x-6 @3xl:grid-cols-[minmax(0,1fr)_14rem]'>
      <div className='flex flex-col gap-1'>
        <h3 className='text-sm font-semibold'>{paragraph.heading}</h3>
        <p data-paragraph={paragraph.id} className='text-sm leading-7'>
          {paragraph.segments.map((segment, index) => (
            <SegmentView key={index} segment={segment} {...handlers} />
          ))}
        </p>
      </div>
      <div>
        {hasComment && (
          <MarginComment status={comment} onResolve={onResolveComment} />
        )}
      </div>
    </div>
  );
}

function idleToneOf(isIdle: boolean) {
  if (isIdle) {
    return 'opacity-0';
  }
  return 'opacity-100';
}

type AgentPointerProps = {
  agent: DocAgent;
  pointer: Pointer;
};

/** The pointer glides with a transition on its position and fades once its agent has nothing to do. */
export function AgentPointer({ agent, pointer }: AgentPointerProps) {
  const isIdle = pointer.target === null;
  const iconStyle = { color: seriesColorOf(agent.series) };

  return (
    <span
      data-pointer={agent.id}
      aria-hidden='true'
      className={cn(
        'pointer-events-none absolute top-0 left-0 z-10 flex items-start transition-[translate,opacity] duration-700 ease-(--ease-in-out-strong) motion-reduce:transition-none',
        idleToneOf(isIdle)
      )}
    >
      <MousePointerIcon style={iconStyle} className='size-4 fill-current' />
      <span
        style={gemStyleOf(agent)}
        className='gem-plate mt-3 flex items-center gap-1.5 rounded-full px-2 py-0.5 text-[11px] font-medium whitespace-nowrap'
      >
        {agent.name}
        <span className='opacity-80'>{pointer.action}</span>
        <span className='tabular-nums'>{formatCost(pointer.spendUsd)}</span>
      </span>
    </span>
  );
}

/** Where along its paragraph each agent rests, so two pointers on one paragraph do not cover each other. */
export const POINTER_REACH: Record<AgentId, number> = {
  writer: 0.42,
  reviewer: 0.12,
};

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

import {
  CHANGE_ORDER,
  type AgentId,
  type ChangeId,
  type ParagraphId,
} from './data';

export type DocView = 'doc' | 'table';

export type ChangeStatus =
  'hidden' | 'typing' | 'pending' | 'accepted' | 'rejected';

export type CommentStatus = 'hidden' | 'typing' | 'posted' | 'resolved';

export type Pointer = {
  /** The paragraph the agent is on, or null while it is idle and its pointer fades. */
  target: ParagraphId | null;
  action: string;
  spendUsd: number;
};

export type DocState = {
  view: DocView;
  pointers: Record<AgentId, Pointer>;
  changes: Record<ChangeId, ChangeStatus>;
  comment: CommentStatus;
};

export type Decision = 'accepted' | 'rejected';

export type DocAction =
  | { type: 'pointer'; agent: AgentId; pointer: Pointer }
  | { type: 'change'; id: ChangeId; status: ChangeStatus }
  | { type: 'comment'; status: CommentStatus }
  | { type: 'decided'; id: ChangeId; decision: Decision }
  | { type: 'acceptAll' }
  | { type: 'view'; view: DocView }
  | { type: 'batch'; actions: DocAction[] };

type Step = SessionStep<DocState, DocAction>;

const IDLE: Pointer = { target: null, action: 'Idle', spendUsd: 0 };

export const INITIAL: DocState = {
  view: 'doc',
  pointers: { writer: IDLE, reviewer: IDLE },
  changes: { c1: 'hidden', c2: 'hidden' },
  comment: 'hidden',
};

export function pendingIdsOf(state: DocState) {
  return CHANGE_ORDER.filter((id) => state.changes[id] === 'pending');
}

function decided(state: DocState, id: ChangeId, decision: Decision): DocState {
  if (state.changes[id] !== 'pending') {
    return state;
  }
  return { ...state, changes: { ...state.changes, [id]: decision } };
}

function acceptAll(state: DocState): DocState {
  let next = state;
  for (const id of pendingIdsOf(state)) {
    next = decided(next, id, 'accepted');
  }
  return next;
}

export function reducer(state: DocState, action: DocAction): DocState {
  switch (action.type) {
    case 'pointer': {
      const pointers = { ...state.pointers, [action.agent]: action.pointer };
      return { ...state, pointers };
    }
    case 'change': {
      const changes = { ...state.changes, [action.id]: action.status };
      return { ...state, changes };
    }
    case 'comment':
      return { ...state, comment: action.status };
    case 'decided':
      return decided(state, action.id, action.decision);
    case 'acceptAll':
      return acceptAll(state);
    case 'view':
      return { ...state, view: action.view };
    case 'batch': {
      let next = state;
      for (const inner of action.actions) {
        next = reducer(next, inner);
      }
      return next;
    }
  }
}

function frame(after: number, actions: DocAction[]): Step {
  return { after, action: { type: 'batch', actions } };
}

function pointing(
  agent: AgentId,
  target: ParagraphId | null,
  action: string,
  spendUsd: number
): DocAction {
  return { type: 'pointer', agent, pointer: { target, action, spendUsd } };
}

function hasDecidedFirst(state: DocState) {
  return state.changes.c1 !== 'pending';
}

function hasNothingPending(state: DocState) {
  return pendingIdsOf(state).length === 0;
}

/** One character every tick while a suggestion types itself. */
export const TYPE_TICK_MS = 45;

/** A request that waits on a person is answered by the demonstration after this long. */
const DECIDE_AFTER_MS = 2500;

export const SCRIPT: Step[] = [
  frame(800, [pointing('writer', 'proposal', 'Reading', 0.004)]),
  frame(1300, [
    pointing('writer', 'proposal', 'Suggesting an edit', 0.007),
    { type: 'change', id: 'c1', status: 'typing' },
  ]),
  frame(2100, [
    { type: 'change', id: 'c1', status: 'pending' },
    pointing('writer', 'proposal', 'Suggested an edit', 0.011),
    pointing('reviewer', 'problem', 'Reading', 0.003),
  ]),
  frame(1200, [
    pointing('reviewer', 'problem', 'Commenting', 0.005),
    { type: 'comment', status: 'typing' },
  ]),
  frame(1600, [
    { type: 'comment', status: 'posted' },
